/**
 * Minimal safe Service Worker
 *
 * The previous sw.js was generated by an old version of next-pwa + Workbox.
 * It had a very aggressive NetworkFirst catch-all for *all* requests (including /api/* and navigation)
 * plus a huge stale precache list of old _next chunks.
 *
 * This was causing:
 * - /api/auth/session (and other API calls) to be intercepted/cached
 * - useSession() / React Query to stay in "loading" forever on mobile
 * - Stale chunk serving on deploys (different JS hashes)
 * - Worse behavior on mobile networks / installed PWAs
 *
 * This minimal version:
 * - Claims control immediately
 * - Cleans up old Workbox caches on activate
 * - Does NOT intercept or cache any requests (pure network passthrough)
 *
 * This lets Next.js, NextAuth, and all data fetching work normally on mobile and desktop.
 * The custom PWA install prompt + offline indicator still function (they don't require routing).
 */

const SW_VERSION = 'minimal-1';

self.addEventListener('install', (event) => {
  console.log('[SW] Installing minimal safe worker', SW_VERSION);
  // Activate immediately, don't wait for old tabs to close
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  console.log('[SW] Activating minimal safe worker', SW_VERSION);

  event.waitUntil(
    (async () => {
      // Clean up any old Workbox / offline caches from previous versions
      const cacheNames = await caches.keys();
      await Promise.all(
        cacheNames.map((cacheName) => {
          const isOldCache =
            cacheName.includes('workbox') ||
            cacheName.includes('offlineCache') ||
            cacheName.includes('start-url') ||
            cacheName.includes('precache');

          if (isOldCache) {
            console.log('[SW] Deleting old cache:', cacheName);
            return caches.delete(cacheName);
          }
        })
      );

      // Take control of all clients immediately
      await self.clients.claim();
      console.log('[SW] Minimal SW activated and claimed clients');
    })()
  );
});

// No 'fetch' event listener at all.
// All requests (HTML, JS chunks, CSS, images, /api/*, auth, etc.) go straight to the network.
// This completely avoids the previous problematic NetworkFirst behavior.
